CREATE TABLE "c_Customer" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Customer_customer_no" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Customer')));
CREATE TABLE "c_Employee" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Employee_employee_no" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Employee')));
CREATE TABLE "c_InventoryItem" ("id" BIGINT NOT NULL, "a_InventoryItem_quantity" BIGINT NOT NULL, "r_ProductInventory_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_ProductInventory_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_ProductInventory_source_id" IS NOT NULL));
CREATE TABLE "c_Invoice" ("id" BIGINT NOT NULL, "a_Invoice_invoice_no" TEXT NOT NULL, "a_Invoice_amount" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Party" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Party_name" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Customer','Employee','Party','Vendor')));
CREATE TABLE "c_Payment" ("id" BIGINT NOT NULL, "a_Payment_amount" NUMERIC NOT NULL, "a_Payment_paid_at" TIMESTAMP NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Product" ("id" BIGINT NOT NULL, "a_Product_sku" TEXT NOT NULL, "a_Product_cost" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_PurchaseOrder" ("id" BIGINT NOT NULL, "a_PurchaseOrder_po_no" TEXT NOT NULL, "a_PurchaseOrder_total" NUMERIC NOT NULL, "r_VendorPurchaseOrders_source_id" BIGINT, "r_VendorPurchaseOrders_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_VendorPurchaseOrders_source_dtype" IS NULL OR "r_VendorPurchaseOrders_source_dtype" IN ('Vendor')), CHECK ((TRUE) OR "r_VendorPurchaseOrders_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_VendorPurchaseOrders_source_id" IS NOT NULL));
CREATE TABLE "c_SalesOrder" ("id" BIGINT NOT NULL, "a_SalesOrder_so_no" TEXT NOT NULL, "a_SalesOrder_total" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Shipment" ("id" BIGINT NOT NULL, "a_Shipment_tracking_no" TEXT NOT NULL, "r_SalesOrderShipments_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_SalesOrderShipments_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_SalesOrderShipments_source_id" IS NOT NULL));
CREATE TABLE "c_Vendor" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Vendor_vendor_no" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Vendor')));
CREATE TABLE "c_Warehouse" ("id" BIGINT NOT NULL, "a_Warehouse_code" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_CustomerSalesOrders" ("r_CustomerSalesOrders_source_id" BIGINT NOT NULL, "r_CustomerSalesOrders_source_dtype" TEXT NOT NULL, "r_CustomerSalesOrders_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_CustomerSalesOrders_source_id", "r_CustomerSalesOrders_target_id"), UNIQUE ("r_CustomerSalesOrders_target_id"), CHECK ("r_CustomerSalesOrders_source_dtype" IS NULL OR "r_CustomerSalesOrders_source_dtype" IN ('Customer')));
CREATE TABLE "l_InvoicePayments" ("r_InvoicePayments_source_id" BIGINT NOT NULL, "r_InvoicePayments_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_InvoicePayments_source_id", "r_InvoicePayments_target_id"), UNIQUE ("r_InvoicePayments_target_id"));
CREATE TABLE "l_PurchaseOrderProducts" ("r_PurchaseOrderProducts_source_id" BIGINT NOT NULL, "r_PurchaseOrderProducts_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PurchaseOrderProducts_source_id", "r_PurchaseOrderProducts_target_id"));
CREATE TABLE "l_SalesOrderInvoices" ("r_SalesOrderInvoices_source_id" BIGINT NOT NULL, "r_SalesOrderInvoices_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_SalesOrderInvoices_source_id", "r_SalesOrderInvoices_target_id"), UNIQUE ("r_SalesOrderInvoices_target_id"));
CREATE TABLE "l_SalesOrderProducts" ("r_SalesOrderProducts_source_id" BIGINT NOT NULL, "r_SalesOrderProducts_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_SalesOrderProducts_source_id", "r_SalesOrderProducts_target_id"));
CREATE TABLE "l_WarehouseInventory" ("r_WarehouseInventory_source_id" BIGINT NOT NULL, "r_WarehouseInventory_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_WarehouseInventory_source_id", "r_WarehouseInventory_target_id"), UNIQUE ("r_WarehouseInventory_target_id"));
ALTER TABLE "c_Customer" ADD CONSTRAINT "fk_c_Customer_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Party" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Employee" ADD CONSTRAINT "fk_c_Employee_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Party" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_InventoryItem" ADD CONSTRAINT "fk_c_InventoryItem_0" FOREIGN KEY ("r_ProductInventory_source_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_PurchaseOrder" ADD CONSTRAINT "fk_c_PurchaseOrder_0" FOREIGN KEY ("r_VendorPurchaseOrders_source_id", "r_VendorPurchaseOrders_source_dtype") REFERENCES "c_Vendor" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Shipment" ADD CONSTRAINT "fk_c_Shipment_0" FOREIGN KEY ("r_SalesOrderShipments_source_id") REFERENCES "c_SalesOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Vendor" ADD CONSTRAINT "fk_c_Vendor_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Party" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_CustomerSalesOrders" ADD CONSTRAINT "fk_l_CustomerSalesOrders_0" FOREIGN KEY ("r_CustomerSalesOrders_source_id", "r_CustomerSalesOrders_source_dtype") REFERENCES "c_Customer" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_CustomerSalesOrders" ADD CONSTRAINT "fk_l_CustomerSalesOrders_1" FOREIGN KEY ("r_CustomerSalesOrders_target_id") REFERENCES "c_SalesOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_InvoicePayments" ADD CONSTRAINT "fk_l_InvoicePayments_0" FOREIGN KEY ("r_InvoicePayments_source_id") REFERENCES "c_Invoice" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_InvoicePayments" ADD CONSTRAINT "fk_l_InvoicePayments_1" FOREIGN KEY ("r_InvoicePayments_target_id") REFERENCES "c_Payment" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PurchaseOrderProducts" ADD CONSTRAINT "fk_l_PurchaseOrderProducts_0" FOREIGN KEY ("r_PurchaseOrderProducts_source_id") REFERENCES "c_PurchaseOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PurchaseOrderProducts" ADD CONSTRAINT "fk_l_PurchaseOrderProducts_1" FOREIGN KEY ("r_PurchaseOrderProducts_target_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderInvoices" ADD CONSTRAINT "fk_l_SalesOrderInvoices_0" FOREIGN KEY ("r_SalesOrderInvoices_source_id") REFERENCES "c_SalesOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderInvoices" ADD CONSTRAINT "fk_l_SalesOrderInvoices_1" FOREIGN KEY ("r_SalesOrderInvoices_target_id") REFERENCES "c_Invoice" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderProducts" ADD CONSTRAINT "fk_l_SalesOrderProducts_0" FOREIGN KEY ("r_SalesOrderProducts_source_id") REFERENCES "c_SalesOrder" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SalesOrderProducts" ADD CONSTRAINT "fk_l_SalesOrderProducts_1" FOREIGN KEY ("r_SalesOrderProducts_target_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_WarehouseInventory" ADD CONSTRAINT "fk_l_WarehouseInventory_0" FOREIGN KEY ("r_WarehouseInventory_source_id") REFERENCES "c_Warehouse" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_WarehouseInventory" ADD CONSTRAINT "fk_l_WarehouseInventory_1" FOREIGN KEY ("r_WarehouseInventory_target_id") REFERENCES "c_InventoryItem" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_CustomerSalesOrders"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_SalesOrder" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_CustomerSalesOrders" l WHERE l."r_CustomerSalesOrders_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: CustomerSalesOrders'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_CustomerSalesOrders_target" AFTER INSERT OR UPDATE OR DELETE ON "c_SalesOrder" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerSalesOrders"();
CREATE CONSTRAINT TRIGGER "ct_CustomerSalesOrders_link" AFTER INSERT OR UPDATE OR DELETE ON "l_CustomerSalesOrders" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerSalesOrders"();
CREATE FUNCTION "require_InvoicePayments"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Payment" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_InvoicePayments" l WHERE l."r_InvoicePayments_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: InvoicePayments'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_InvoicePayments_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Payment" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_InvoicePayments"();
CREATE CONSTRAINT TRIGGER "ct_InvoicePayments_link" AFTER INSERT OR UPDATE OR DELETE ON "l_InvoicePayments" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_InvoicePayments"();
