CREATE CONSTRAINT TRIGGER "ct_SalesOrderInvoices_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Invoice" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_SalesOrderInvoices"();
CREATE CONSTRAINT TRIGGER "ct_SalesOrderInvoices_link" AFTER INSERT OR UPDATE OR DELETE ON "l_SalesOrderInvoices" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_SalesOrderInvoices"();
CREATE FUNCTION "require_WarehouseInventory"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_InventoryItem" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_WarehouseInventory" l WHERE l."r_WarehouseInventory_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: WarehouseInventory'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_WarehouseInventory_target" AFTER INSERT OR UPDATE OR DELETE ON "c_InventoryItem" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_WarehouseInventory"();
